def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    dom=[c for c,n in cnt.most_common(1)[0]][0]
    seen=[[False]*w for _ in range(h)]
    noise=[]
    for i in range(h):
        for j in range(w):
            c=g[i][j]
            if g[i][j]!=dom and not seen[i][j]:
                # flood fill same color 4-conn
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b)); 
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; st.append((x,y))
                if len(comp)<=1:
                    noise.extend(comp)
    for i,j in noise:
        nb=[g[a][b] for a,b in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)) if 0<=i<a<h and 0<=j<b<w]
        if nb: g[i][j]=Counter(nb).most_common(1)[0][0]
    return g

