# verify tie cases: try 'tie -> smallest color', 'tie -> largest', 'tie -> dom' on demo
def f(g, tiebreak):
    h,w=len(g),len(g[0])
    dom=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; noise=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=dom and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; st.append((x,y))
                if len(comp)==1: noise.append((i,j,c))
    out=[r[:] for r in g]
    for i,j,c in noise:
        nb=[out[a][b] for a,b in ((i+1,j),(i-1,j),(i,j+1),(i,j-1)) if 0<=a<h and 0<=b<w]
        cntn=Counter(nb)
        top,maxv=cntn.most_common(1)[0]
        cand=[k for k,n in cntn.items() if n==maxv]
        if len(cand)==1: pick=cand[0]
        elif tiebreak=='min': pick=min(cand); 
        elif tiebreak=='max': pick=max(cand)
        elif tiebreak=='dom': pick=dom
        else: pick=top
        out[i][j]=pick
    return out
